INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65213564', 65213564, 'analyze_legacy', 'Komisi Pemilihan Umum', 'central', 'KPU  PROVINSI KEPULAUAN RIAU', 'Kendaraan R4 Eselon II', 'Jasa Lainnya', 'E-Purchasing', 'Kepulauan Riau, Tanjung Pinang (Kota)', 1080000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 pkt', 'Kendaraan R4 Eselon II', 'Toyota Innova Zenix Q Hybrid CVT Modellista TSS adalah MPV mewah dengan mesin hibrida 2.0L (M20A-FXS), transmisi CVT, dan dilengkapi fitur keselamatan canggih Toyota Safety Sense (TSS) serta body kit Modellista, menawarkan tenaga kombinasi sekitar 184 PS, torsi 187 Nm (bensin) + 206 Nm (motor listrik) dengan efisiensi tinggi dan kenyamanan premium seperti jok Captain Seat dengan ventilasi. Spesifikasi Utama: >Mesin: 2.0L 4-silinder, DOHC, Dual VVT-i (M20A-FXS). >Sistem Hibrida: Generasi ke-5 dengan motor listrik untuk efisiensi lebih baik. >Kapasitas Mesin: 1987 cc. >Tenaga Maksimum (Kombinasi): Sekitar 184 PS. >Torsi Maksimum (Kombinasi): Bensin 187 Nm + Motor Listrik 206 Nm. >Transmisi: 10-Speed Direct Shift CVT (Power Split Device). >Penggerak: Front Wheel Drive (FWD). >Kapasitas Penumpang: 7 Orang (biasanya jok captain seat di baris kedua). Fitur Unggulan: >Toyota Safety Sense (TSS): Pre-Collision System, Lane Departure Alert, Adaptive Cruise Control, dll.. >Modelista Body Kit: Estetika lebih sporty di depan, samping, dan belakang. >Interior Premium: Jok kulit dengan ventilasi (varian tertinggi), layar sentuh 10 inci. >Fitur Lain: Smart Entry, Spion Otomatis, Sensor Parkir, Kamera 360 (tergantung varian). Dimensi & Detail Lain: >Dimensi (P x L x T): 4755 mm x 1850 mm x 1795 mm. >Ground Clearance: 185 mm. >Velg: 18 inci (ban 225/50 R18). >Suspensi: MacPherson Strut (depan), Torsion Beam (belakang).', 180000000, 'high', 'Spesifikasi menunjukkan kendaraan dinas eselon dengan varian premium berfitur mewah, termasuk body kit Modellista dan interior captain seat berventilasi. Unsur estetika dan kenyamanan premium tersebut tidak tampak esensial untuk kebutuhan operasional dasar lembaga, sehingga terdapat indikasi pemborosan pada pemilihan trim/fitur yang terlalu tinggi.', NULL, NULL, 3, 1, 1, 1, 1, 1991757);
