INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65174878', 65174878, 'analyze_legacy', 'Kementerian Sekretariat Negara', 'central', 'SEKRETARIAT WAKIL PRESIDEN', 'Jasa Konsultansi Tenaga Ahli Junior Komunikasi Eksternal dan Kemitraan P2S (TA JKEK) Tahun 2026', 'Jasa Konsultansi', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 5432631000, 'January 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 paket', '1) Mengkoordinasikan dgn para stakeholder rencana kerja penyusunan/penguatan Strategi Komunikasi P3S. 2) Menyusun dan menindaklanjut pelaksanaan rekomendasi atas kebutuhan penguatan kapasitas K/L kunci dlm pelaksanaan Strategi Komunikasi. 3) Menyusun rekomendasi konsep strategi dan dukungan teknis dlm penyelenggaraan kegiataan terkait isu stunting. 4) Mengkoordinasikan pelaporan/peliputan media massa dlm diseminasi isu terkait stunting secara tepat dan akurat. 5) Menyusun pelaporan hasil analisis dan rekomendasi atas monitoring media terkait isu stunting. 6) Menyusun dan memantau rencana kerja/program/materi/desain/konten dlm pelaksanaan Strategi Komunikasi P3S secara menyeluruh berjalan baik. 7) Melaksanakan fungsi sebagai liaison officer dlm program/kegiatan kerja sama internasional. 8) Menjaga profesionalitas, integritas, loyalitas, dan kesetiaan kepada Setwapres. 9) Melaksanakan tugas yg diberikan oleh Setwapres dan Team Leader dgn penuh tanggungjawab.', '1) Mempunyai pendidikan minimal S1 dengan pengalaman 7 tahun atau S2 dengan pengalaman 5 tahun pada bidang Komunikasi/Jurnalistik/Sosial/Psikologi atau bidang lain yang relevan. 2) Memiliki kemampuan komunikasi dan networking dalam pelaksanaan program skala nasional/internasional. 3) Mempunyai pengalaman kerja minimal 5 tahun terutama dalam penyusunan dan pelaksanaan kampanye publik melalui media massa/media konvensional/media sosial dan pengembangan kemitraan. 4) Mempunyai pengalaman bekerja sama dengan Kementerian/Lembaga pemerintah daerah, lembaga swasta dan mitra pembangunan lain dalam berbagai kegiatan yang terkait dengan perubahan perilaku, promosi, atau kampanye media. 5) Mempunyai jejaring kerja dan hubungan yang luas dan baik dengan kalangan media massa konvensional maupun media sosial. 6) Mempunyai pengetahuan yang baik tentang komunikasi untuk perubahan perilaku melalui kampanye. 7) Memiliki kemampuan melakukan analisis masalah, mencari solusi, dan merealisasikannya. 8) Mempunyai pengalaman dalam mengembangkan dan mengelola kemitraan dengan pemerintah dan swasta, terutama isu-isu gizi dan kesehatan. 9) Memiliki kemampuan interpersonal dan komunikasi yang sangat baik, serta mampu menyelesaikan berbagai tugas secara bersamaan dan tepat waktu dengan kualitas yang sangat baik. 10) Mempunyai kemampuan advokasi, membangun kapasitas dan kolaborasi kerja, serta memiliki jejaring kerja yang luas pada Kementerian/Lembaga, pemerintah daerah, LSM, swasta, mitra pembangunan, dan pemangku kepentingan terkait lainnya. 11) Mempunyai pengalaman dalam pengembangan dan pelaksanaan program kemitraan antara pemerintah dengan lembaga non-pemerintah. 12) Memiliki kemampuan menyusun dan menyajikan konten media komunikasi.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1992124);
