INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65177468', 65177468, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN EKONOMI KEGIATAN KOORDINASI STRATEGIS PERENCANAAN INPRES JALAN DAERAH (IJD) DAN DAK SEKTOR BIDANG TRANSPORTASI 2026', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 360000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '7. Lingkup Pekerjaan a. Mengkompilasi dan menganalisis peraturan mengenai sektor transportasi jalan yang merupakan kewenangan daerah; b. Mengkompilasi dan menganalisis data mengenai sektor transportasi jalan yang merupakan kewenangan daerah 3 Tahun sebelumnya; c. Memberikan masukan terhadap penyusunan Rancangan Arah kebijakan DAK Sektor transportasi jalan dan Inpres Jalan Daerah; d. Memberikan masukan terhadap penyusunan Kebijakan DAK Sektor transportasi jalan dan Inpres Jalan Daerah mendukung Tematik pengutamaan dalam Prioritas Nasional; e. Memberikan masukan terhadap penyusunan Kriteria Lokasi prioritas dan penanganan kegiatan DAK Sektor transportasi jalan dan Inpres Jalan Daerah; f. Memberikan analisis terkait penyusunan formulasi alokasi DAK Sektor transportasi jalan dan Inpres Jalan Daerah yang dialokasikan per daerah; g. Memberikan analisis terkait penyusunan Rencana Kerja DAK Sektor Transportasi Jalan dan Daftar Prioritas Penanganan Inpres Jalan Daerah; h. Melakukan analisis kebijakan DAK Sektor Transportasi Jalan dan Inpres Jalan Daerah eksisting; i. Melakukan analisis alokasi dan daerah penerima DAK Sektor Transportasi Jalan dan Inpres Jalan Daerah eksisting; j. Menyusun rekomendasi kebijakan DAK Sektor Transportasi Jalan dan Inpres Jalan Daerah.', '1. Diutamakan menggunakan konsultan dalam Negeri, dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP) 2. Memiliki Nomor Pokok Wajib Pajak (NPWP) 3. Pendidikan minimal S1 (bidang hukum, perencanaan wilayah dan kota, perencanaan pendanaan pembangunan, pembiayaan pembangunan, ilmu ekonomi, manajemen, administrasi negara, ilmu pemerintahan atau bidang lain yang relevan), dibuktikan dengan ijazah jenjang pendidikan yang telah ditempuh; 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan yang sejenis dalam kurun 10 (sepuluh) tahun terakhir baik di lingkungan pemerintah, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak/lama kontrak kerja; 5. Pernah mempunyai kontrak dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang 50% (lima puluh persen) nilai HPS;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1995124);
