INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65177096', 65177096, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'TENAGA ALIH DAYA TENAGA ADMINISTRASI ANGGARAN PADA PPK DI BIRO PERENCANAAN, ORGANISASI DAN TATA LAKSANA', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 25585896, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Melaksanakan fungsi operator pengajuan pembayaran pada PPK di Biro Perencanaan, Organisasi dan Tata Laksana; 2. Menyiapkan dan memproses dokumen pengajuan pembayaran sesuai ketentuan; 3. Mengelola, menatausahakan, dan mengarsipkan dokumen pertanggungjawaban pembayaran secara tertib dan sistematis; 4. Melakukan pencatatan dan rekapitulasi administrasi keuangan; 5. Mendukung monitoring administrasi keuangan PPK; 6. Berkoordinasi dengan bendahara dan unit kerja terkait; 7. Melaksanakan tugas administratif lain yang relevan sesuai arahan PPK.', '1. Tersedianya layanan dukungan administratif operasional dalam proses pengajuan pembayaran pada PPK di Biro Perencanaan, Organisasi dan Tata Laksana; 2. Tertibnya penatausahaan dan pengelolaan dokumen pertanggungjawaban pembayaran yang terdokumentasi dengan baik sesuai ketentuan yang berlaku; 3. Tersusunnya rekapitulasi administrasi keuangan sebagai bahan pendukung monitoring administrasi pengelolaan keuangan PPK; 4. Terlaksananya dukungan administrasi pengelolaan keuangan secara tepat waktu dan akuntabel di bawah arahan dan pengendalian PPK; 5. Terjaganya pemisahan peran antara dukungan administratif yang diberikan oleh Tenaga Alih Daya dan kewenangan pengambilan keputusan yang tetap berada pada ASN', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1995156);
