INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65176583', 65176583, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN  JASA KONSULTAN JUNIOR PERENCANAAN TRANSPORTASI LAUT KEGIATAN PENYUSUNAN KEBIJAKAN PERENCANAAN TRANSPORTASI LAUT', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 142560000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', 'Lingkup Pekerjaan 1. Melakukan analisis dan memberikan masukan terhadap review evaluasi pelaksanaan pembangunan kegiatan-kegiatan prioritas di sektor transportasi Perhubungan Laut; 2. Memberikan masukan terhadap analisis yang mendukung penyusunan RKP 2027 yang selaras dengan Rancangan RPJMN 2025-2029, dan Renstra K/L mitra sektor Direktorat Konektivitas dan Infrastruktur Logistik Bappenas dengan Tema RKP 2027; 3. Memberikan masukan terhadap penyusunan narasi RKP dan penyusunan Renja K/L berdasarkan hasil analisis serta evaluasi dari konsep Green Port; 4. Memberikan masukan terhadap hasil evaluasi RKP 2026, khususnya untuk aspek penerapan Green Port dan juga integrasi layanan keperintisan; 5. Memberikan masukan terhadap hasil evaluasi tahun kedua kegiatan RPJMN 2025-2029 melalui reviu terhadap kebijakan-kebijakan terkait konsep Green Port yang ada di Indonesia; menyusun instrumen evaluasi dari penerapan konsep Green Port, analisis penerapan konsep Green Port; dan memberikan masukan terhadap aspek perencanaan sektor transportasi laut dan juga fokus pada pembahasan dekarbonisasi laut; 6. Menyusun instrumen evaluasi terhadap skema pelayanan keperintisan sektor perhubungan; 7. Mengidentifikasi strategi untuk mengintegrasikan layanan keperintisan sektor perhubungan.', '1. Diutamakan menggunakan Jasa Konsultan Junior dalam Negeri, dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP) 2. Memiliki Nomor Pokok Wajib Pajak (NPWP) 3. Pendidikan minimal S2 (bidang perencanaan dan pembangunan kebijakan transportasi) dibuktikan dengan ijazah jenjang pendidikan yang telah ditempuh; 4. Memiliki pengalaman kerja di bidang perencanaan dan analisis kebijakan transportasi minimal 3 tahun, dibuktikan dengan kontrak kerja sebelumnya/ surat keputusan/surat keterangan kerja/surat referensii kerja sebelumnya; 5. Memiliki pengalaman bekerja dalam sektor pemerintahan minimal 4 tahun; 6. Memiliki pengalaman dalam proyek/kegiatan di sektor transportasi; 7. Memiliki publikasi penelitian/jurnal di sektor transportasi baik di level Internasional maupun Nasional (melampirkan link publikasi tulisan); 8. Memiliki pengalaman dalam mengikuti workshop, seminar, training atau sejenis (melampirkan bukti referensi/sertifikat); 9. Memiliki pengalaman organisasi yang memadai; 10. Memiliki pengalaman menjadi presenter dalam seminar baik di lingkup Nasional atau Internasional; 11. Memiliki kemampuan menulis laporan serta membuat presentasi (melampirkan bukti referensi/kontrak kerja/bukti contoh hasil tulisan).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1996994);
