INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65176820', 65176820, 'analyze_legacy', 'Kementerian Sekretariat Negara', 'central', 'SEKRETARIAT WAKIL PRESIDEN', 'Jasa Konsultansi Tenaga Ahli Pemantauan dan Pelaporan Berbasis Data TP2S Tahun 2026', 'Jasa Konsultansi', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 5432631000, 'January 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 paket', '1) Melakukan koordinasi dgn K/L terkait data laporan kegiatan pelaksanaan P3S. 2) Melakukan pemantauan program/kegiatan K/L dan Pemerintah Daerah dlm upaya pencapaian target percepatan penurunan stunting. 3) Mengkompilasi data terkait P3S dari pelaporan K/L maupun berbagai studi sbg bahan analisis dan rekomendasi kebijakan oleh Setwapres. 4) Menyiapkan pelaporan tertulis secara periodik dan akhir proyek tepat waktu dgn kualitas yg baik. 5) Mengoptimalkan sistem informasi pelaporan internal utk penguatan pemantauan dan evaluasi. 6) Menyiapkan bahan pelaporan sesuai dgn kebutuhan. 7) Menyiapkan bahan komunikasi dan koordinasi dgn kementerian/lembaga. 8) Melakukan inventarisasi, pengembangan, analisis data terkait P3S pd para Stakeholder sbg bahan penyusunan rekomendasi kebijakan oleh Setwapres. 9) Menjaga profesionalitas, integritas, loyalitas, dan kesetiaan kepada pemberi kerja. 10) Melaksanakan tugas yg diberikan oleh Setwapres dan Team Leader dgn penuh tanggungjawab.', '1) Mempunyai pendidikan minimal S1 dengan pengalaman 7 tahun atau S2 dengan pengalaman 5 tahun pada bidang Statistik/Akuntansi/Ilmu Ekonomi/Kebijakan Publik/Kesehatan Masyarakat, atau bidang lain yang relevan. 2) Mempunyai pengalaman kerja profesional, khususnya dalam melakukan pemantauan dan penyusunan laporan program/kegiatan. 3) Mempunyai pengalaman bekerja sama dengan berbagai pemangku kepentingan pada Kementerian/Lembaga, pemerintah daerah dan lembaga pemerintah khususnya terkait dengan isu stunting atau isu kesehatan lainnya. 4) Mampu membuat laporan tertulis dan menyusun penyajian dalam presentasi dengan kualitas yang baik. 5) Mampu mengoperasikan perangkat lunak analisis statistik (SPPS, Stata, dan Tableau), mengolah, menganalisis, dan menampilkan data statistik/informasi. 6) Mempunyai keterampilan teknis menyusun perencanaan program/kegiatan, penyelesaian pelaporan, dan kerangka pemantauan dan evaluasi. 7) Mempunyai kemampuan advokasi, membangun kapasitas dan kolaborasi kerja, serta memiliki jejaring kerja yang luas pada Kementerian/Lembaga, pemerintah daerah, LSM, swasta, mitra pembangunan, dan pemangku kepentingan terkait lainnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1997854);
