INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65220006', 65220006, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS TENAGA KERJA, TRANSMIGRASI, DAN ENERGI KABUPATEN ADMINISTRASI KEPULAUAN SERIBU', 'BELANJA JASA TENAGA AHLI - PENDAMPING KEWIRAUSAHAAN TERPADU (PJLP DINAS TENAGA KERJA TRANSMIGRASI DAN ENERGI)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Adm. Kepulauan Seribu (Kab.)', 143506350, 'January 2026', 'APBD', 1, 1, '1 Paket', '1. Ruang Lingkup pekerjaan adalah Penyediaan Jasa PJLP Pendamping Kewirausahaan Terpadu 2. Lokasi pekerjaan Penyediaan Jasa PJLP Pendamping Kewirausahaan Terpadu adalah pada Suku Dinas Tenaga Kerja, Transmigrasi dan Energi Kabupaten Administrasi Kepulauan Seribu', 'b. Persyaratan Kualifikasi Administrasi dan Teknis persyaratan kualifikasi administrasi/ legalitas meliputi: 1) Memenuhi ketentuan peraturan perundang-undangan untuk menjalankan kegiatan/usaha. 2) Memiliki identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP/Paspor/Surat Keterangan Domisili Tinggal); 3) Memiliki status valid keterangan Wajib Pajak berdasarkan hasil konfirmasi status Wajib Pajak; 4) Surat Pernyataan Pakta Integritas. 5) Surat pernyataan yang ditandatangani Peserta yang berisi: a) Tidak dikenakan Sanksi Daftar Hitam b) Keikutsertaannya tidak menimbulkan pertentangan kepentingan pihak yang terkait; c) Tidak dalam pengawasan pengadilan dan/atau sedang menjalani sanksi pidana; dan d) Tidak berstatus Aparatur Sipil Negara, kecuali yang bersangkutan mengambil cuti di luar tanggungan Negara persyaratan kualifikasi teknis meliputi: 1) Memiliki kemampuan untuk memenuhi kebutuhan jasa lainnya; 2) Pendidikan minimal Sarjana (S1) atau setara dibuktikan dengan melampirkan Ijazah dan Transkrip Nilai; 3) Diutamakan bagi yang telah memiliki usaha dan atau pengalaman memberikan pendampingan usaha dibuktikan dengan melampirkan Sertifikat Pendamping Kewirausahaan atau Sertifikat Kompetensi Kewirausahaan dari BNSP serta melampirkan Surat Keterangan memiliki usaha (jika ada); 4) Mampu mengoperasikan Komputer minimal Program Microsoft Office (Word, Excel, Power Point), mengoperasikan internet dan menguasai aplikasi yang berkaitan dengan pelaksanaan tugas pendamping kewirausahaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1998265);
